using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata via the generic GetTypeInfo<T>()
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got JsonTypeInfo<Person>: CreateObject is {(personInfo.CreateObject is not null ? "set" : "null")}");

// 2) Probe without throwing using TryGetTypeInfo (added in .NET 8)
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
{
    Console.WriteLine($"TryGetTypeInfo(Person) succeeded — Kind: {found.Kind}");
}
else
{
    Console.WriteLine("TryGetTypeInfo(Person) returned false");
}

// Probe for a type whose metadata might NOT be available
// (use a resolver that only handles Person)
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine(
        new LimitedResolver())
};

if (limited.TryGetTypeInfo(typeof(string), out _))
{
    Console.WriteLine("TryGetTypeInfo(string) on limited resolver: available");
}
else
{
    Console.WriteLine("TryGetTypeInfo(string) on limited resolver: NOT available (no exception thrown)");
}

Console.WriteLine("Done.");

public record Person(string Name, int Age);

/// <summary>A resolver that only provides metadata for Person.</summary>
file class LimitedResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
        {
            return JsonMetadataServices.CreateObjectInfo<Person>(options,
                new JsonObjectInfoValues<Person>
                {
                    ObjectCreator = () => new Person("", 0),
                    SerializeHandler = (w, v) =>
                    {
                        w.WriteStartObject();
                        w.WriteString("name", v.Name);
                        w.WriteNumber("age", v.Age);
                        w.WriteEndObject();
                    }
                });
        }
        return null; // signals "I don't handle this type"
    }
}

